using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Reflection.Emit;
using System.Threading;
using LastCallBBS.ModAPI;

namespace LastCallBBS.Launcher;

/// <summary>
/// Plays audio generated by mods through the game's mixer. The mixer asks each voice to add its
/// samples to the output; a voice is a subclass of the game's abstract voice source, created by a
/// subclass of its abstract sound data. Both subclasses are emitted here and call StreamCalls.
/// </summary>
internal static class SoundStreams
{
    // The name the game's per-sound volume table looks up; it has no entry, so the volume is 1.
    private const string SoundName = "mods/stream";

    // Sound categories pick the volume setting: 0 is EFFECT, 1 is MUSIC.
    private const int MusicCategory = 1;

    private static Type _voiceBase, _dataBase, _sound;
    private static MethodInfo _mix, _finished, _seek, _tell, _dispose, _createVoice, _play;
    private static ConstructorInfo _voiceBaseCtor, _dataBaseCtor, _voiceCtor, _dataCtor;
    private static FieldInfo _soundData, _soundCategory;
    private static object _category;
    private static string _failure;

    /// <summary>Finds the game code and emits the subclasses. Returns one message if it couldn't.</summary>
    public static List<string> Verify()
    {
        try
        {
            Resolve();
            Log.Info("Sound streams: OK");
            return new List<string>();
        }
        catch (ShapeMismatchException e)
        {
            Log.Error($"Sound streams: FAILED - {e.Message}");
            return new List<string> { $"sound streams: {e.Message}" };
        }
    }

    public static IStreamControl Start(IAudioSource source, float volume, IModLog log)
    {
        Resolve();
        var state = new StreamState(source, volume, log);
        object data = _dataCtor.Invoke(new object[] { SoundName, state });
        object sound = Activator.CreateInstance(_sound);
        _soundData.SetValue(sound, data);
        _soundCategory.SetValue(sound, _category);
        GameSounds.InvokeStatic(_play, sound, false, 0f, 0f, false, 1f, 0.0);
        if (!state.VoiceCreated)
        {
            state.Stop();
            throw new InvalidOperationException("the game has no audio device");
        }
        return state;
    }

    internal static object CreateVoice(object state)
    {
        ((StreamState)state).VoiceCreated = true;
        return _voiceCtor.Invoke(new[] { state });
    }

    private static void Resolve()
    {
        if (_failure != null)
            throw new ShapeMismatchException(_failure);
        if (_dataCtor != null)
            return;
        try
        {
            Assembly game = HookHost.Game;
            Type[] types = game.GetTypes();
            _sound = CodeShape.RequireType(game, "Sound");
            _play = GameSounds.PlayCall();
            Type shortPtr = typeof(short).MakePointerType();
            Type[] mixParameters = { shortPtr, typeof(int), typeof(float), typeof(bool), typeof(bool) };

            // The voice source: the abstract class with an abstract (short*, int, float, bool, bool) mix method.
            _voiceBase = CodeShape.Single(types.Where(t => t.IsClass && t.IsAbstract && t.IsPublic &&
                Abstracts(t).Any(m => m.ReturnType == typeof(void) && Parameters(m).SequenceEqual(mixParameters))), "voice source class");
            MethodInfo[] voice = Abstracts(_voiceBase).ToArray();
            if (voice.Length != 5)
                throw new ShapeMismatchException($"the voice source class has {voice.Length} abstract methods, not 5");
            _mix = Method(voice, typeof(void), mixParameters, "voice mix method");
            _finished = Method(voice, typeof(bool), Type.EmptyTypes, "voice finished method");
            _seek = Method(voice, typeof(void), new[] { typeof(double) }, "voice seek method");
            _tell = Method(voice, typeof(double), Type.EmptyTypes, "voice position method");
            _dispose = Method(voice, typeof(void), Type.EmptyTypes, "voice dispose method");
            _voiceBaseCtor = CodeShape.Single(CodeShape.InstanceConstructors(_voiceBase).OfType<ConstructorInfo>()
                .Where(c => c.GetParameters().Length == 0 && (c.IsPublic || c.IsFamily)), "voice source constructor");

            // The sound data: the abstract class whose only abstract method creates a voice, constructed from a name.
            _dataBase = CodeShape.Single(types.Where(t => t.IsClass && t.IsAbstract && t.IsPublic &&
                Abstracts(t).Count() == 1 && Abstracts(t).All(m => m.ReturnType == _voiceBase && m.GetParameters().Length == 0)), "sound data class");
            _createVoice = Abstracts(_dataBase).Single();
            _dataBaseCtor = CodeShape.Single(CodeShape.InstanceConstructors(_dataBase).OfType<ConstructorInfo>()
                .Where(c => Parameters(c).SequenceEqual(new[] { typeof(string) }) && (c.IsPublic || c.IsFamily)), "sound data constructor");

            // Sound: the data and the volume category.
            _soundData = CodeShape.SingleField(_sound, f => !f.IsStatic && f.IsPublic && f.FieldType == _dataBase, "Sound's data field");
            _soundCategory = CodeShape.SingleField(_sound, f => !f.IsStatic && f.IsPublic && f.FieldType.IsEnum, "Sound's category field");
            _category = Enum.ToObject(_soundCategory.FieldType, MusicCategory);
            if (_sound.GetConstructor(Type.EmptyTypes) == null)
                throw new ShapeMismatchException("Sound has no public parameterless constructor");

            Emit();
        }
        catch (ShapeMismatchException e)
        {
            _failure = e.Message;
            throw;
        }
    }

    private static IEnumerable<MethodInfo> Abstracts(Type t) =>
        t.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly).Where(m => m.IsAbstract);

    private static Type[] Parameters(MethodBase m) => m.GetParameters().Select(p => p.ParameterType).ToArray();

    private static MethodInfo Method(IEnumerable<MethodInfo> methods, Type returns, Type[] parameters, string what) =>
        CodeShape.Single(methods.Where(m => m.ReturnType == returns && Parameters(m).SequenceEqual(parameters) && (m.IsPublic || m.IsFamily)), what);

    private static void Emit()
    {
        ModuleBuilder module = AppDomain.CurrentDomain.DefineDynamicAssembly(new AssemblyName("LastCallBBS.Streams"), AssemblyBuilderAccess.Run)
            .DefineDynamicModule("Streams");

        // The voice: holds the stream's state and passes every call to StreamCalls.
        TypeBuilder voice = module.DefineType("LastCallBBS.Streams.StreamVoice", TypeAttributes.Public | TypeAttributes.Sealed | TypeAttributes.Class, _voiceBase);
        FieldBuilder voiceState = voice.DefineField("State", typeof(object), FieldAttributes.Public);
        ILGenerator ctor = voice.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, new[] { typeof(object) }).GetILGenerator();
        ctor.Emit(OpCodes.Ldarg_0);
        ctor.Emit(OpCodes.Call, _voiceBaseCtor);
        ctor.Emit(OpCodes.Ldarg_0);
        ctor.Emit(OpCodes.Ldarg_1);
        ctor.Emit(OpCodes.Stfld, voiceState);
        ctor.Emit(OpCodes.Ret);
        Forward(voice, voiceState, _mix, nameof(StreamCalls.Mix));
        Forward(voice, voiceState, _finished, nameof(StreamCalls.Finished));
        Forward(voice, voiceState, _seek, nameof(StreamCalls.Seek));
        Forward(voice, voiceState, _tell, nameof(StreamCalls.Tell));
        Forward(voice, voiceState, _dispose, nameof(StreamCalls.Dispose));
        Type voiceType = voice.CreateType();
        _voiceCtor = voiceType.GetConstructor(new[] { typeof(object) });

        // The sound data: constructed from the name and the state, creates a voice for each play.
        TypeBuilder data = module.DefineType("LastCallBBS.Streams.StreamSound", TypeAttributes.Public | TypeAttributes.Sealed | TypeAttributes.Class, _dataBase);
        FieldBuilder dataState = data.DefineField("State", typeof(object), FieldAttributes.Public);
        ctor = data.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, new[] { typeof(string), typeof(object) }).GetILGenerator();
        ctor.Emit(OpCodes.Ldarg_0);
        ctor.Emit(OpCodes.Ldarg_1);
        ctor.Emit(OpCodes.Call, _dataBaseCtor);
        ctor.Emit(OpCodes.Ldarg_0);
        ctor.Emit(OpCodes.Ldarg_2);
        ctor.Emit(OpCodes.Stfld, dataState);
        ctor.Emit(OpCodes.Ret);
        Forward(data, dataState, _createVoice, nameof(StreamCalls.CreateVoice));
        Type dataType = data.CreateType();
        _dataCtor = dataType.GetConstructor(new[] { typeof(string), typeof(object) });
    }

    /// <summary>Overrides <paramref name="target"/> with a call to StreamCalls.<paramref name="call"/>(state, arguments...).</summary>
    private static void Forward(TypeBuilder type, FieldInfo state, MethodInfo target, string call)
    {
        Type[] parameters = Parameters(target);
        MethodAttributes access = target.Attributes & MethodAttributes.MemberAccessMask;
        MethodBuilder m = type.DefineMethod(target.Name, access | MethodAttributes.Virtual | MethodAttributes.HideBySig, target.ReturnType, parameters);
        ILGenerator il = m.GetILGenerator();
        il.Emit(OpCodes.Ldarg_0);
        il.Emit(OpCodes.Ldfld, state);
        for (int i = 1; i <= parameters.Length; i++)
            il.Emit(OpCodes.Ldarg_S, (byte)i);
        il.Emit(OpCodes.Call, typeof(StreamCalls).GetMethod(call));
        if (target.ReturnType != typeof(void) && !target.ReturnType.IsValueType)
            il.Emit(OpCodes.Castclass, target.ReturnType);
        il.Emit(OpCodes.Ret);
        type.DefineMethodOverride(m, target);
    }
}

/// <summary>One stream: the mod's source, read by the mixer on the audio thread.</summary>
internal sealed class StreamState : IStreamControl
{
    private readonly IAudioSource _source;
    private readonly IModLog _log;
    private float[] _buffer = new float[ModSounds.BufferFrames * 2];
    private long _frames;
    private volatile float _volume;
    private volatile bool _stopped, _ended;

    public StreamState(IAudioSource source, float volume, IModLog log)
    {
        _source = source;
        _volume = volume;
        _log = log;
    }

    public bool VoiceCreated { get; set; }

    public float Volume
    {
        get => _volume;
        set => _volume = value;
    }

    public bool IsPlaying => !_stopped && !_ended;
    public long FramesPlayed => Interlocked.Read(ref _frames);
    public bool Finished => _stopped || _ended;
    public double Seconds => (double)FramesPlayed / ModSounds.SampleRate;

    public void Stop() => _stopped = true;
    public void End() => _ended = true;

    /// <summary>Adds up to <paramref name="count"/> interleaved stereo samples to the game's output.</summary>
    public unsafe void Mix(short* output, int count, float volume, bool swap)
    {
        if (_stopped || _ended)
            return;
        int frames = count / 2;
        if (_buffer.Length < frames * 2)
            _buffer = new float[frames * 2];
        int got;
        try
        {
            got = _source.Read(_buffer, frames);
        }
        catch (Exception e)
        {
            _ended = true;
            _log.Error($"Audio stream stopped: {e.GetType().Name}: {e.Message}\n{e.StackTrace}");
            return;
        }
        got = Math.Max(0, Math.Min(frames, got));
        float gain = volume * _volume * 32767f;
        float[] buffer = _buffer;
        int samples = got * 2;
        for (int i = 0; i < samples; i++)
        {
            float f = buffer[swap ? i ^ 1 : i];
            if (f > 1f)
                f = 1f;
            else if (!(f >= -1f))
                f = f < -1f ? -1f : 0f; // also NaN
            int mixed = output[i] + (int)(f * gain);
            output[i] = (short)(mixed > short.MaxValue ? short.MaxValue : mixed < short.MinValue ? short.MinValue : mixed);
        }
        Interlocked.Add(ref _frames, got);
        if (got < frames)
            _ended = true;
    }
}

/// <summary>Called by the emitted voice and sound classes, which live in another assembly.</summary>
public static class StreamCalls
{
    public static unsafe void Mix(object state, short* output, int count, float volume, bool loop, bool swap) =>
        ((StreamState)state).Mix(output, count, volume, swap);

    public static bool Finished(object state) => ((StreamState)state).Finished;
    public static void Seek(object state, double seconds) { }
    public static double Tell(object state) => ((StreamState)state).Seconds;
    public static void Dispose(object state) => ((StreamState)state).End();
    public static object CreateVoice(object state) => SoundStreams.CreateVoice(state);
}
